 "content": "def transform(grid):
    """Recolor every cell on a uniform, full-width or full-height line to 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    rows = [r for r in range(h) if all(grid[r][c] == grid[r][0] for c in range(w))]
    cols = [c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h))]
    for r in rows:
        for c in range(w):
            out[r][c] = 2
    for c in cols:
        for r in range(h):
            out[r][c] = 2
    return out
